mapper.update:
UPDATE task_execution
SET status = 'SUCCESS',
    end_time = UTC_TIMESTAMP(3),
    result_summary = CAST(#{resultJson} AS JSON)
WHERE instance_id = #{instanceId}
  AND attempt_no = #{attemptNo}
  AND worker_id = #{workerId}
  AND lease_version = #{leaseVersion}
  AND status = 'RUNNING'

UPDATE task_execution
SET status = 'FAILED',
    end_time = UTC_TIMESTAMP(3),
    error_message = #{errorMessage},
    retry_due_at = TIMESTAMPADD(SECOND, #{retryDelaySeconds}, UTC_TIMESTAMP(3))
WHERE instance_id = #{instanceId}
  AND attempt_no = #{attemptNo}
  AND worker_id = #{workerId}
  AND lease_version = #{leaseVersion}
  AND status = 'RUNNING'

UPDATE task_execution
SET status = 'FAILED', end_time = UTC_TIMESTAMP(3), error_message = #{errorMessage}
WHERE instance_id = #{instanceId}
  AND attempt_no = #{attemptNo}
  AND worker_id = #{workerId}
  AND lease_version = #{leaseVersion}
  AND status = 'RUNNING'
